INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (4, 'Mesin tidak mau berjalan', 'Motor tidak berputar atau mesin tidak merespons saat pedal diinjak.', 'Catu daya tidak tersedia, koneksi listrik bermasalah, atau sistem motor/control box mengalami gangguan.', 'Periksa sumber listrik, konektor, dan control box. Pastikan catu daya 220–240 V 1 phase tersedia sebelum menguji kembali mesin.', 'Matikan mesin dan lepaskan sumber listrik sebelum memeriksa koneksi atau control box.', 'Panduan pemeriksaan umum JUKI DDL-7000A');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (4, 'Benang atas sering putus', 'Benang jarum putus berulang saat proses menjahit.', 'Ukuran atau pemasangan jarum tidak sesuai, jalur benang kurang tepat, atau tegangan benang terlalu tinggi.', 'Periksa pemasangan jarum DB×1, jalur benang, dan sesuaikan tegangan benang dengan material yang digunakan.', 'Matikan mesin sebelum mengganti jarum atau melakukan penyesuaian pada area jarum.', 'Panduan troubleshooting umum mesin lockstitch JUKI');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (4, 'Jahitan loncat', 'Stitch tidak terbentuk secara konsisten atau terdapat bagian jahitan yang terlewat.', 'Jarum bengkok atau tumpul, pemasangan jarum tidak tepat, atau hubungan jarum dengan hook perlu diperiksa.', 'Ganti jarum dengan DB×1 yang sesuai dan pastikan posisi serta pemasangannya benar. Jika masalah berlanjut, periksa timing hook.', 'Matikan mesin dan lepaskan sumber listrik sebelum memeriksa jarum atau hook.', 'Panduan troubleshooting umum JUKI DDL-7000A');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (4, 'Benang bawah bermasalah', 'Benang bawah putus, tersangkut, atau hasil jahitan bagian bawah tidak stabil.', 'Pemasangan bobbin atau jalur benang bawah tidak tepat, atau tegangan bobbin tidak sesuai.', 'Periksa pemasangan bobbin, jalur benang bawah, kondisi bobbin case, dan sesuaikan tegangan sesuai kebutuhan material.', 'Matikan mesin sebelum melepas bobbin case atau membersihkan area hook.', 'Panduan troubleshooting umum mesin lockstitch JUKI');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (4, 'Presser foot tidak mengangkat dengan baik', 'Presser foot sulit terangkat atau tinggi angkat tidak sesuai.', 'Mekanisme pengangkat presser foot tidak disetel dengan benar atau terdapat hambatan pada mekanisme.', 'Periksa mekanisme pengangkat presser foot dan pastikan gerakannya bebas. DDL-7000A memiliki lift sekitar 5,5 mm dengan tangan dan 13 mm menggunakan knee.', 'Matikan mesin sebelum melakukan penyetelan mekanisme presser foot.', 'Data spesifikasi JUKI DDL-7000AS-7 dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (4, 'Pelumasan tidak normal', 'Mesin terdengar kasar, panas berlebih, atau bagian bergerak tidak bekerja dengan lancar.', 'Level oli kurang atau sistem forced lubrication tidak bekerja sebagaimana mestinya.', 'Periksa level oli dan sistem pelumasan. Gunakan oli yang sesuai, yaitu JUKI Corporation Oil 7 atau NEW DEFRIX Oil No. 1 sesuai spesifikasi.', 'Matikan mesin sebelum memeriksa sistem pelumasan dan hindari kontak langsung dengan bagian mesin yang bergerak.', 'Data spesifikasi pelumasan JUKI DDL-7000AS-7');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (4, 'Jahitan tidak sesuai panjang yang diatur', 'Panjang stitch aktual berbeda dari pengaturan atau hasil jahitan tidak konsisten.', 'Mekanisme feed dog tidak bekerja normal, penyetelan panjang jahitan kurang tepat, atau kondisi material memengaruhi feeding.', 'Periksa pengaturan panjang jahitan, kondisi feed dog, dan pastikan material dapat bergerak dengan stabil. Panjang jahitan maksimum spesifikasi adalah 5 mm.', 'Matikan mesin sebelum melakukan pemeriksaan pada feed mechanism.', 'Data spesifikasi JUKI DDL-7000AS-7 dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (4, 'Motor atau penggerak tidak normal', 'Suara motor tidak normal, putaran tidak stabil, atau respons pedal terganggu.', 'Gangguan pada AC servomotor, koneksi motor, control box, atau sistem main-shaft direct-drive.', 'Periksa koneksi motor dan control box. Pastikan sistem main-shaft direct-drive tidak mengalami hambatan mekanis. Jika gangguan berlanjut, lakukan pemeriksaan oleh teknisi.', 'Matikan mesin dan lepaskan sumber listrik sebelum memeriksa motor, control box, atau main shaft.', 'Data sistem penggerak JUKI DDL-7000AS-7 dan panduan pemeriksaan umum');
